vertex:
#version 300 es
layout(location = 0) in vec3 position;
layout(location = 3) in vec4 vertexColor;

uniform mat4 viewProjection;
uniform mat4 model;
out vec3 v_position;
out vec4 v_color;

void main() {
  v_position = position;
  v_color = vertexColor;
  gl_Position = viewProjection * model * vec4(position, 1.0);
}

fragment:
#version 300 es
precision highp float;

in vec3 v_position;
in vec4 v_color;
uniform float opacity;

out vec4 fragColor;

void main() {
  // node 0 attribute
  vec3 n0 = v_position;
  // node 1 swizzle
  vec2 n1 = n0.xy;
  // node 2 constant
  vec2 n2 = vec2(0.25, -0.5);
  // node 3 binary
  vec2 n3 = (n1 - n2);
  // node 4 unary
  float n4 = length(n3);
  // node 5 constant
  float n5 = 0.6666666666666666;
  // node 6 binary
  float n6 = (n4 * n5);
  // node 7 constant
  vec4 n7 = vec4(1.0, 0.9, 0.4, 0.875);
  // node 8 constant
  float n8 = 0.0;
  // node 9 binary
  float n9 = (n6 - n8);
  // node 10 constant
  float n10 = 2.0;
  // node 11 binary
  float n11 = (n9 * n10);
  // node 12 unary
  float n12 = clamp(n11, 0.0, 1.0);
  // node 13 constant
  vec4 n13 = vec4(0.0, -0.5, -0.4, 0.0);
  // node 14 binary
  vec4 n14 = (n13 * n12);
  // node 15 binary
  vec4 n15 = (n7 + n14);
  // node 16 constant
  float n16 = 0.5;
  // node 17 binary
  float n17 = step(n16, n6);
  // node 18 constant
  vec4 n18 = vec4(-0.8, -0.4, 0.4, 0.0);
  // node 19 binary
  vec4 n19 = (n18 * n17);
  // node 20 binary
  vec4 n20 = (n15 + n19);
  // node 21 constant
  float n21 = 0.5;
  // node 22 binary
  float n22 = (n6 - n21);
  // node 23 constant
  float n23 = 2.0;
  // node 24 binary
  float n24 = (n22 * n23);
  // node 25 unary
  float n25 = clamp(n24, 0.0, 1.0);
  // node 26 constant
  vec4 n26 = vec4(-0.2, 0.0, -0.30000000000000004, 0.0);
  // node 27 binary
  vec4 n27 = (n26 * n25);
  // node 28 binary
  vec4 n28 = (n20 + n27);
  // node 29 constant
  vec4 n29 = vec4(1.0, 1.0, 1.0, 0.5);
  // node 30 attribute
  vec4 n30 = v_color;
  // node 31 swizzle
  float n31 = n30.x;
  // node 32 mix
  vec4 n32 = mix(n28, n29, n31);
  vec4 c = n32;
  fragColor = vec4(c.rgb, c.a * opacity);
}
